const idColor = (id) => {
  let hash = 0;
  for (let i = 0; i < String(id || "").length; i += 1) hash = (hash * 31 + String(id).charCodeAt(i)) >>> 0;
  return MEMBER_DOT_COLORS[hash % MEMBER_DOT_COLORS.length];
};
const THEME_KEY = "pilateacher_theme_v1";
