function normalizeDb(data, staff) {
  const d = data && typeof data === "object" ? data : {};
  return {
    settings: { center: d.settings?.center ?? "", staff: d.settings?.staff ?? (staff || ""), payRate: Number(d.settings?.payRate) || DEF_RATE, groupRate: Number(d.settings?.groupRate) || DEF_GROUP_RATE, templates: Array.isArray(d.settings?.templates) ? d.settings.templates : [], scheduleColors: normalizeScheduleColors(d.settings?.scheduleColors), hiddenClientIds: Array.isArray(d.settings?.hiddenClientIds) ? d.settings.hiddenClientIds.filter((value) => typeof value === "string" && value) : [] },
    members: Array.isArray(d.members) ? d.members.filter(Boolean).map((m) => ({
      ...blankMember(staff), ...m,
      id: m.id || uid(),
      status: ["ended", "hold", "inactive"].includes(m.status) ? m.status : "active",
      regular: Number(m.regular) || 0, service: Number(m.service) || 0, total: Number(m.total) || 0,
      defaultLessonDuration: lessonDurationOf(m),
      focus: Array.isArray(m.focus) ? m.focus : [],
      perf: Array.isArray(m.perf) && m.perf.length ? m.perf : DEFAULT_PERF.map((x) => ({ ...x })),
      inbody: Array.isArray(m.inbody) ? m.inbody.filter((r) => r && r.date).map((r) => ({ ...r, id: r.id || uid() })) : [],
      notes: Array.isArray(m.notes) ? m.notes.filter(Boolean) : [],
      payments: Array.isArray(m.payments) ? m.payments.filter(Boolean) : [],
    })) : [],
    schedule: Array.isArray(d.schedule) ? dedupeScheduleByLessonId(d.schedule.filter((x) => x && x.date)).map((x) => ({
      ...x,
      /* 기구는 강사가 고른 값이다 — 있는 일정만 정리하고, 없는 옛 일정에 값을 만들어 넣지 않는다 */
      ...(Array.isArray(x.equipmentIds) ? { equipmentIds: normalizeEquipmentIds(x.equipmentIds) } : {}),
      attendees: Array.isArray(x.attendees) && x.attendees.length
        ? x.attendees.filter((a) => a && a.memberId).map((a) => ({ ...a, status: STATUS[a.status] ? a.status : "booked" }))
        : x.memberId ? [{ memberId: x.memberId, status: STATUS[x.status] ? x.status : "booked", deductFrom: x.deductFrom || null, noshowFee: x.noshowFee ?? null }] : [],
    })).filter((x) => x.attendees.length || x.equip || x.personal || x.unlinkedMemberDeleted || x.type === "그룹" || (Array.isArray(x.equipmentIds) && x.equipmentIds.length)) : [],
  };
}
